\set ON_ERROR_STOP on
SELECT 'PHIEN '||pg_backend_pid()||' '||current_setting('application_name')||' '||clock_timestamp();
BEGIN;
SELECT 1 FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86' FOR SHARE; SELECT 1 FROM event_schema.tbl_ticket_types WHERE id='ffb36fc7-e30a-4efe-987f-ca5533520453' FOR SHARE;
SELECT 'TRUONG|event.sale_ends_at|'||COALESCE((SELECT CASE WHEN (sale_ends_at) IS NULL THEN 'THIEU' WHEN (sale_ends_at) = '2026-12-02 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (sale_ends_at) = '2026-12-30 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(sale_ends_at)::text END FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|event.starts_at|'||COALESCE((SELECT CASE WHEN (starts_at) IS NULL THEN 'THIEU' WHEN (starts_at) = '2026-12-03 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (starts_at) = '2026-12-31 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(starts_at)::text END FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|event.checkin_starts_at|'||COALESCE((SELECT CASE WHEN (checkin_starts_at) IS NULL THEN 'THIEU' WHEN (checkin_starts_at) = '2026-12-03 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (checkin_starts_at) = '2026-12-31 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(checkin_starts_at)::text END FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|event.ends_at|'||COALESCE((SELECT CASE WHEN (ends_at) IS NULL THEN 'THIEU' WHEN (ends_at) = '2026-12-04 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (ends_at) = '2027-01-01 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(ends_at)::text END FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|event.checkin_ends_at|'||COALESCE((SELECT CASE WHEN (checkin_ends_at) IS NULL THEN 'THIEU' WHEN (checkin_ends_at) = '2026-12-04 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (checkin_ends_at) = '2027-01-01 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(checkin_ends_at)::text END FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|event.ticket_types.configured_quantity|'||COALESCE((SELECT CASE WHEN (configured_quantity) IS NULL THEN 'THIEU' WHEN (configured_quantity) = 100000 THEN 'CU' WHEN (configured_quantity) = 96000 THEN 'DICH' ELSE 'KHAC:'||(configured_quantity)::text END FROM event_schema.tbl_ticket_types WHERE id='ffb36fc7-e30a-4efe-987f-ca5533520453'), 'THIEU_DONG');
SELECT 'PHU|event.so_dong_events|'||count(*) FROM event_schema.tbl_events WHERE id='3e7c1df9-ada4-4081-94a1-548b80a5da86';
COMMIT;
